fn max_cat_pts() i64 {
    return 256;
}

fn cat_pt(b_: ScreenPt, h_: f64, lift: f64, p_: StillPt) ScreenPt {
    return cx_new(ScreenPtS{ .x = (b_.x + (p_.x * h_)), .y = (b_.y - ((p_.y + lift) * h_)) });
}

fn cat_pts(b_: ScreenPt, h_: f64, lift: f64, ps: *CxList(StillPt), i_: i64) *CxList(ScreenPt) {
    return (if ((i_ >= cx_list_len(ps))) cx_ll_empty(ScreenPt) else cx_ll_concat(cx_ll_of(ScreenPt, &[_]ScreenPt{ cat_pt(b_, h_, lift, cx_list_at(ps, i_)) }), cat_pts(b_, h_, lift, ps, (i_ +% 1))));
}

fn cat_poly(b_: ScreenPt, h_: f64, lift: f64, poly: StillPoly) *CxList(DrawCmd) {
    return (if ((cx_list_len(poly.pts) > max_cat_pts())) cx_ll_empty(DrawCmd) else push_poly(poly.color, cat_pts(b_, h_, lift, poly.pts, 0)));
}

fn cat_polys(b_: ScreenPt, h_: f64, lift: f64, ps: *CxList(StillPoly), i_: i64) *CxList(DrawCmd) {
    return (if ((i_ >= cx_list_len(ps))) cx_ll_empty(DrawCmd) else cx_ll_concat(cat_poly(b_, h_, lift, cx_list_at(ps, i_)), cat_polys(b_, h_, lift, ps, (i_ +% 1))));
}

fn cat_draw(right: f64, forward: f64, height: f64, pose_idx: i64, lift: f64, cf: f64, view_w: f64) *CxList(DrawCmd) {
    return b0: { const base_ = project(cx_new(Vec3S{ .right = right, .forward = forward, .height = @as(f64, @bitCast(@as(i64, 0))) }), cf, view_w); break :b0 b1: { const top_ = project(cx_new(Vec3S{ .right = right, .forward = forward, .height = height }), cf, view_w); break :b1 b2: { const h_: f64 = (base_.y - top_.y); break :b2 (if ((h_ < @as(f64, @bitCast(@as(i64, 4607182418800017408))))) cx_ll_empty(DrawCmd) else cat_polys(base_, h_, lift, (if ((pose_idx == 0)) pose_rest_polys() else (if ((pose_idx == 1)) pose_stride_polys() else (if ((pose_idx == 2)) pose_frozen_polys() else (if ((pose_idx == 3)) pose_coil_polys() else (if ((pose_idx == 4)) pose_flight_polys() else (if ((pose_idx == 5)) pose_land_polys() else (if ((pose_idx == 6)) pose_collapse_polys() else cx_ll_empty(StillPoly)))))))), 0)); }; }; };
}

