fn u_pig_herd() f64 {
    return u_at_metres(@as(f64, @bitCast(@as(i64, 4652684608003899392))));
}

fn u_mid_tower() f64 {
    return u_at_metres(@as(f64, @bitCast(@as(i64, 4658045826700935168))));
}

fn profile_pt(w: *CxList(Segment), s_: RiderState) ProfilePt {
    return cx_new(ProfilePtS{ .dist = route_distance(w, s_.segment, s_.along), .v_ = s_.v_, .tilt = s_.tilt, .seg = s_.segment });
}

fn profile_from(w: *CxList(Segment), s_: RiderState, n_: i64) *CxList(ProfilePt) {
    return (if ((n_ <= 0)) cx_ll_empty(ProfilePt) else (if (is_finished(s_, w)) cx_ll_of(ProfilePt, &[_]ProfilePt{ profile_pt(w, s_) }) else cx_ll_concat(cx_ll_of(ProfilePt, &[_]ProfilePt{ profile_pt(w, s_) }), profile_from(w, get_next_rider_state(s_, w), (n_ -% 1)))));
}

fn profile_frames() i64 {
    return 4000;
}

fn speed_profile() *CxList(ProfilePt) {
    return profile_from(build_world(), initial_rider_state(), profile_frames());
}

fn scaled(v_: f64) []const u8 {
    return cx_show_int(cx_real_to_int((v_ * @as(f64, @bitCast(@as(i64, 4636737291354636288))))));
}

fn coords(ps: *CxList(f64), i_: i64) []const u8 {
    return (if ((i_ >= cx_list_len(ps))) "" else cx_concat(cx_concat("\x02", scaled(cx_list_at(ps, i_))), coords(ps, (i_ +% 1))));
}

fn cmd_line(c_: DrawCmd) []const u8 {
    return cx_concat(cx_concat(cx_concat(cx_concat(cx_concat(cx_concat(cx_concat(cx_concat(cx_concat("\x32\x02", cx_show_int(c_.tag)), "\x02"), cx_show_int(c_.color)), "\x02"), cx_show_int(cx_real_to_int((c_.strength * @as(f64, @bitCast(@as(i64, 4652007308841189376))))))), "\x02"), cx_show_int(@divTrunc(cx_list_len(c_.pts), 2))), coords(c_.pts, 0)), (if ((c_.tag >= 4)) cx_concat(cx_concat("\x02", cx_show_int(c_.color2)), coords(c_.geom, 0)) else ""));
}

fn all_cmds(cs: *CxList(DrawCmd), i_: i64) []const u8 {
    return (if ((i_ >= cx_list_len(cs))) "" else cx_concat(cx_concat(cmd_line(cx_list_at(cs, i_)), "\x02\x46\x02"), all_cmds(cs, (i_ +% 1))));
}

fn scene_line(name: []const u8, u_: f64) []const u8 {
    return cx_concat(cx_concat(cx_concat(cx_concat(cx_concat("\x2d\x32\x27\x2c\x27\x02", name), "\x02"), cx_show_int(sky_color(scene_step_at(u_)))), "\x02"), cx_show_int(horizon_color(scene_step_at(u_))));
}

fn prof_pt(p_: ProfilePt) []const u8 {
    return cx_concat(cx_concat(cx_concat(cx_concat(cx_concat(cx_concat(cx_show_int(cx_real_to_int(p_.dist)), "\x02"), cx_show_int(cx_real_to_int((p_.v_ * @as(f64, @bitCast(@as(i64, 4652007308841189376))))))), "\x02"), cx_show_int(cx_real_to_int((p_.tilt * @as(f64, @bitCast(@as(i64, 4652007308841189376))))))), "\x02"), cx_show_int(p_.seg));
}

fn prof_all(ps: *CxList(ProfilePt), i_: i64) []const u8 {
    return (if ((i_ >= cx_list_len(ps))) "" else cx_concat(cx_concat(prof_pt(cx_list_at(ps, i_)), "\x02\x46\x02"), prof_all(ps, (i_ +% 1))));
}

fn opening() void {
    return b0: { _ = cx_print_line(cx_concat("\x39\x2f\x2a\x36\x2b\x31\x27\x02", cx_show_int(cx_list_len(speed_profile())))); _ = cx_print_line(prof_all(speed_profile(), 0)); _ = cx_print_line(scene_line("\x1f\x11\x1d\x49\x14\x0d\x15\x16", u_pig_herd())); _ = cx_print_line(all_cmds(spike_frame_at(u_pig_herd()), 0)); _ = cx_print_line(scene_line("\x1a\x11\x16\x49\x0e\x10\x1b\x0d\x15", u_mid_tower())); _ = cx_print_line(all_cmds(spike_frame_at(u_mid_tower()), 0)); break :b0; };
}

fn cx_entry() void {
    opening();
}

pub fn main() void {
    const stack_bytes: usize = 512 * 1024 * 1024;
    const t = std.Thread.spawn(.{ .stack_size = stack_bytes }, cx_entry, .{}) catch @panic("spawn");
    t.join();
}

